// Overdue-invoice reminders: fixed schedule, paid invoices ignored, one level at a time, a level already recorded in the sheet is not drafted again.

var ALIASES = {
  invoice_number: ['invoice_number', 'invoice', 'invoice_no', 'number', 'no'],
  client_name: ['client_name', 'client', 'customer', 'name'],
  client_email: ['client_email', 'email', 'e-mail', 'customer_email'],
  amount: ['amount', 'total', 'amount_due'],
  due_date: ['due_date', 'due', 'date_due'],
  status: ['status', 'state'],
  paid_date: ['paid_date', 'paid_on', 'payment_date'],
  reminder_level: ['reminder_level', 'reminders_sent', 'level'],
  last_reminder_date: ['last_reminder_date', 'last_reminder', 'reminded_on']
};
var PAID_STATUSES = ['paid', 'settled', 'closed', 'cancelled', 'canceled', 'void'];

function norm(s) { return String(s === undefined || s === null ? '' : s).trim().toLowerCase().replace(/\s+/g, '_'); }

function readField(row, field) {
  var wanted = ALIASES[field];
  for (var key in row) { if (wanted.indexOf(norm(key)) >= 0) return row[key]; }
  return undefined;
}

function two(n) { return (n < 10 ? '0' : '') + n; }

// Accepts YYYY-MM-DD or DD/MM/YYYY (day first); anything else is "unreadable" (null).
function parseDate(v) {
  var s = String(v === undefined || v === null ? '' : v).trim();
  var m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  var y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else {
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (!m) return null;
    d = +m[1]; mo = +m[2]; y = +m[3];
  }
  var t = new Date(Date.UTC(y, mo - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== mo - 1 || t.getUTCDate() !== d) return null;
  return y + '-' + two(mo) + '-' + two(d);
}

function dayNumber(iso) {
  var m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return Math.round(Date.UTC(+m[1], +m[2] - 1, +m[3]) / 86400000);
}

function addDays(iso, days) {
  var m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  var t = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3] + days));
  return t.getUTCFullYear() + '-' + two(t.getUTCMonth() + 1) + '-' + two(t.getUTCDate());
}

// "1,200.50", "1 200,50", "1200", "120 EUR", "$99", 1200 -> number, otherwise null.
// The WHOLE text must be one amount (optional currency at either end): "100-200" or "100 EUR (VAT 20%)" are refused.
var CURRENCY = '(?:\\u20ac|\\$|\\u00a3|eur|euros?|usd|gbp|chf|cad)';
var AMOUNT_FORMS = [
  /^-?\d+(?:[.,]\d+)?$/,
  /^-?\d{1,3}(?:,\d{3})+(?:\.\d+)?$/,
  /^-?\d{1,3}(?:\.\d{3})+(?:,\d+)?$/,
  /^-?\d{1,3}(?:[ \u00a0\u202f]\d{3})+(?:[.,]\d+)?$/
];
function parseAmount(v) {
  if (typeof v === 'number') return isFinite(v) ? v : null;
  var s = String(v === undefined || v === null ? '' : v).trim()
    .replace(new RegExp('^' + CURRENCY + '\\s*', 'i'), '')
    .replace(new RegExp('\\s*' + CURRENCY + '$', 'i'), '').trim();
  if (!AMOUNT_FORMS.some(function (re) { return re.test(s); })) return null;
  s = s.replace(/[ \u00a0\u202f]/g, '');
  var lastComma = s.lastIndexOf(','), lastDot = s.lastIndexOf('.');
  if (lastComma >= 0 && lastDot >= 0) {
    s = lastComma > lastDot ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (lastComma >= 0) {
    s = /,\d{1,2}$/.test(s) ? s.replace(',', '.') : s.replace(/,/g, '');
  }
  var n = parseFloat(s);
  return isFinite(n) ? n : null;
}

function parseSchedule(text) {
  var raw = text === undefined || text === null || text === '' ? '7,21,35' : text;
  var d = String(raw).split(/[,;\s]+/).map(function (x) { return parseInt(x, 10); });
  if (d.length !== 3 || d.some(function (x) { return !(x >= 0 && x < 1000); }) || !(d[0] < d[1] && d[1] < d[2])) {
    throw new Error('Invalid schedule: write three increasing numbers of days, for example 7,21,35.');
  }
  return d;
}

function todayIso(cfg) {
  if (cfg && cfg.today) {
    var d = parseDate(cfg.today);
    if (!d) throw new Error('Setting "today" is unreadable: use YYYY-MM-DD or leave it empty.');
    return d;
  }
  var n = new Date();
  return n.getUTCFullYear() + '-' + two(n.getUTCMonth() + 1) + '-' + two(n.getUTCDate());
}

function money(amount, currency) {
  var cur = currency || 'EUR';
  return amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' ' + cur;
}

function reminderText(level, inv, cfg) {
  var sign = cfg && cfg.sender_name ? String(cfg.sender_name).trim() : '';
  var pay = cfg && cfg.payment_details ? '\n\nHow to pay: ' + cfg.payment_details : '';
  var ref = 'invoice ' + inv.number + ' (' + money(inv.amount, cfg && cfg.currency) + ', due ' + inv.due_date + ')';
  var close = function (word) { return word + (sign ? ',\n' + sign : ''); };
  if (level === 1) {
    return {
      subject: 'Friendly reminder: invoice ' + inv.number + ' is now due',
      body: 'Hello,\n\nOur records show that ' + ref + ' has not been paid yet (' + inv.days_late + ' days late). It may simply have slipped through; if you have already paid, please ignore this message.' + pay + '\n\n' + close('Kind regards')
    };
  }
  if (level === 2) {
    return {
      subject: 'Second reminder: invoice ' + inv.number + ' is ' + inv.days_late + ' days late',
      body: 'Hello,\n\nFurther to my previous reminder, ' + ref + ' is still unpaid (' + inv.days_late + ' days late). Could you confirm the payment date?' + pay + '\n\n' + close('Kind regards')
    };
  }
  return {
    subject: 'Final reminder: invoice ' + inv.number,
    body: 'Hello,\n\nDespite two earlier reminders, ' + ref + ' remains unpaid (' + inv.days_late + ' days late). Unless I receive payment shortly, I will have to apply the late-payment terms of our agreement (adapt this sentence to your own terms).' + pay + '\n\n' + close('Regards')
  };
}

// rows: array of objects (sheet rows). Returns { to_send[], skipped[], today }.
function pickReminders(rows, cfg) {
  var schedule = parseSchedule(cfg && cfg.schedule_days);
  var today = todayIso(cfg);
  var todayNum = dayNumber(today);
  var toSend = [], skipped = [], seen = {};
  rows.forEach(function (r) {
    var n = readField(r, 'invoice_number');
    if (n !== undefined && String(n).trim() !== '') { var k = String(n).trim().toLowerCase(); seen[k] = (seen[k] || 0) + 1; }
  });
  rows.forEach(function (r, idx) {
    var raw = readField(r, 'invoice_number');
    var number = String(raw === undefined || String(raw).trim() === '' ? 'row ' + (idx + 2) : raw).trim();
    function skip(reason) { skipped.push({ invoice_number: number, reason: reason }); }
    var status = norm(readField(r, 'status'));
    var paidOn = String(readField(r, 'paid_date') === undefined ? '' : readField(r, 'paid_date')).trim();
    if (PAID_STATUSES.indexOf(status) >= 0 || paidOn !== '') return skip('already paid or closed');
    if ((seen[number.toLowerCase()] || 0) > 1) return skip('duplicate invoice number (' + seen[number.toLowerCase()] + ' rows): fix before any reminder');
    var due = parseDate(readField(r, 'due_date'));
    var amount = parseAmount(readField(r, 'amount'));
    var email = String(readField(r, 'client_email') === undefined ? '' : readField(r, 'client_email')).trim();
    if (!due) return skip('due date unreadable');
    if (amount === null || amount <= 0) return skip('amount unreadable');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return skip('client e-mail missing or invalid');
    var level = parseInt(readField(r, 'reminder_level'), 10) || 0;
    if (level >= 3) return skip('all 3 reminders already sent: handle manually');
    var last = parseDate(readField(r, 'last_reminder_date'));
    if (last === today) return skip('already reminded today');
    var late = todayNum - dayNumber(due);
    var dueLevel = 0;
    for (var i = 0; i < 3; i++) if (late >= schedule[i]) dueLevel = i + 1;
    if (dueLevel <= level) {
      return skip(late < 0 ? 'not due yet' : 'reminder ' + (level + 1) + ' planned for ' + addDays(due, schedule[level]));
    }
    var next = level + 1; // one level at a time, even if several are overdue
    var inv = { number: number, amount: amount, due_date: due, days_late: late };
    var t = reminderText(next, inv, cfg);
    toSend.push({
      invoice_number: number,
      client_name: String(readField(r, 'client_name') || '').trim(),
      to: email,
      subject: t.subject,
      body: t.body,
      reminder_level: next,
      last_reminder_date: today,
      days_late: late
    });
  });
  return { to_send: toSend, skipped: skipped, today: today };
}


